import { spawnSync } from "node:child_process";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { gunzipSync } from "node:zlib";
import { BACKGROUND_CONTEXT as context } from "@earendil-works/chord/context";
import { createModels } from "@earendil-works/pi-ai/models";
import { fauxAssistantMessage, fauxProvider } from "@earendil-works/pi-ai/providers/faux";
import {
  createRegistry,
  defineDoc,
  defineExtension,
  defineTask,
  defineTool,
  Harness,
  LiveDoc,
  type TaskId,
  type SubmissionId,
} from "@earendil-works/pi-durable";
import { openNodeSqliteStorage } from "@earendil-works/pi-durable/storage/sqlite/node";
import { expect, test } from "vite-plus/test";

// Generated with the real 1.2.0 SDK from /opt/batty2/current/node_modules on
// 2026-10-22, against an isolated temporary database (never production data).
// Gzipped JSON contains sqlite_master DDL and all rows, not a hand-written
// approximation of schema 1. root.commit created a pending background task
// with input { value: 42 } and two document edits in separate commits.
// Keeping the fixture here also lets this test run after 1.2 is uninstalled.
const legacyFixture =
  "";

// Generated by the installed 1.4.0 SDK on 2026-11-02 in an isolated temporary
// database. Contains a sleeping task, a pending task, and a task left running by
// process.exit(73), plus a version-1 pi.live compactionFailure and document deltas.
// No production data is included. All DDL/rows are preserved exactly.
const durable14Fixture =
  "";
const durable14 = {
  sleeping: 8 as TaskId<null>,
  running: 9 as TaskId<number>,
  pending: 10 as TaskId<number>,
};

// Generated with real 1.4.0 Harness.submit and the faux provider on 2026-11-02.
// Each isolated process exited 73 inside the provider request or replay-safe
// tool execution, leaving genuine in-flight built-in tasks and placed inputs.
const durable14GenerationFixture =
  "";
const durable14ToolFixture =
  "";

const legacyDocument = defineDoc<{ items: string[] }>({
  kind: "test.migration",
  version: 1,
  scope: "conversation",
  history: "rewindable",
  fork: "current",
  initial: () => ({ items: [] }),
  checkpointWhen: () => false,
});

function restoreLegacy(path: string, encoded = legacyFixture) {
  const fixture = JSON.parse(gunzipSync(Buffer.from(encoded, "base64")).toString()) as {
    schema: string[];
    tables: Record<string, Record<string, string | number | null>[]>;
  };
  const db = new DatabaseSync(path);
  try {
    for (const sql of fixture.schema) db.exec(sql);
    for (const [table, rows] of Object.entries(fixture.tables)) {
      for (const row of rows) {
        const columns = Object.keys(row);
        db.prepare(
          `INSERT INTO "${table}" (${columns.map((column) => `"${column}"`).join(",")}) VALUES (${columns.map(() => "?").join(",")})`,
        ).run(...Object.values(row));
      }
    }
  } finally {
    db.close();
  }
  return fixture.tables;
}

function schemaVersion(path: string) {
  const db = new DatabaseSync(path, { readOnly: true });
  try {
    return db.prepare("SELECT version FROM durable_schema").get()?.version;
  } finally {
    db.close();
  }
}

function migrationTask(onDeliver: () => void = () => {}) {
  return defineTask<{ value: number }, { phase: "deliver" }, number>({
    name: "test.migration-task",
    version: 1,
    initial: () => ({ phase: "deliver" }),
    phases: {
      deliver: async (task, runtime, ctx) => {
        onDeliver();
        await runtime.commit(
          () => ({
            status: "terminal",
            outcome: { status: "completed", result: task.input.value },
          }),
          ctx,
        );
      },
    },
    abort: (_task, runtime, ctx) =>
      runtime.commit(() => ({ status: "terminal", outcome: { status: "aborted" } }), ctx),
  });
}

const legacyTaskId = 8 as TaskId<number>;

test("real schema-1 database migrates to schema 2 without rewriting documents or tasks", async () => {
  const directory = await mkdtemp(join(tmpdir(), "batty-durable-migration-"));
  const path = join(directory, "legacy.sqlite");
  let harness: Harness | undefined;
  try {
    const before = restoreLegacy(path);
    expect(schemaVersion(path)).toBe(1);
    const storage = await openNodeSqliteStorage(path);
    try {
      expect(schemaVersion(path)).toBe(2);
      const db = new DatabaseSync(path, { readOnly: true });
      try {
        // The task table is rebuilt by migration 2; compare every persisted row,
        // including document bases/deltas and ID/commit-sequence metadata.
        for (const [table, rows] of Object.entries(before)) {
          if (table !== "durable_schema") {
            expect(db.prepare(`SELECT * FROM "${table}" ORDER BY rowid`).all()).toEqual(rows);
          }
        }
      } finally {
        db.close();
      }
    } finally {
      await storage.close(context);
    }
    const registry = createRegistry();
    let delivered = 0;
    registry.install(
      defineExtension({ name: "migration-test", tasks: [migrationTask(() => delivered++)] }),
    );
    harness = await Harness.open(
      await openNodeSqliteStorage(path),
      { models: createModels(), registry },
      context,
    );
    const root = await harness.root(context);
    expect(root.id).toBe(1);
    expect(await harness.snapshot(legacyDocument, root.id, context)).toEqual({
      items: ["before migration", "second committed delta"],
    });
    expect(await harness.getTask(legacyTaskId, context)).toMatchObject({
      input: { value: 42 },
      background: true,
      state: { status: "pending", checkpoint: { phase: "deliver" } },
    });
    expect((await harness.waitForTask(legacyTaskId, context)).state).toEqual({
      status: "terminal",
      outcome: { status: "completed", result: 42 },
    });
    expect(delivered).toBe(1);
    await root.commit(async (tx) => {
      (await tx.doc(legacyDocument, root.id)).items.push("after migration");
    }, context);
    expect(await harness.snapshot(legacyDocument, root.id, context)).toEqual({
      items: ["before migration", "second committed delta", "after migration"],
    });
  } finally {
    await harness?.close(context);
    await rm(directory, { recursive: true, force: true });
  }
});

test("sleeping task persists its deadline and checkpoint, then resumes exactly once after reopen", async () => {
  const directory = await mkdtemp(join(tmpdir(), "batty-durable-sleep-"));
  const path = join(directory, "sleep.sqlite");
  let harness: Harness | undefined;
  let now = 1000;
  let starts = 0;
  let deliveries = 0;
  const sleeper = defineTask<{ at: number }, { phase: "wait" } | { phase: "deliver" }, null>({
    name: "test.sleeper",
    version: 1,
    initial: () => ({ phase: "wait" }),
    phases: {
      wait: (task, runtime, ctx) => {
        starts++;
        return runtime.sleepUntil(task.input.at, { phase: "deliver" }, ctx);
      },
      deliver: (_task, runtime, ctx) => {
        deliveries++;
        return runtime.commit(
          () => ({ status: "terminal", outcome: { status: "completed", result: null } }),
          ctx,
        );
      },
    },
    abort: (_task, runtime, ctx) =>
      runtime.commit(() => ({ status: "terminal", outcome: { status: "aborted" } }), ctx),
  });
  const registry = createRegistry();
  registry.install(defineExtension({ name: "sleep-test", tasks: [sleeper, migrationTask()] }));
  const open = async () =>
    Harness.open(
      await openNodeSqliteStorage(path),
      {
        models: createModels(),
        registry,
        now: () => now,
        onWake: () => {},
      },
      context,
    );
  try {
    // Exercise sleeping against the rebuilt legacy tasks table, not only a fresh schema 2.
    restoreLegacy(path);
    harness = await open();
    const root = await harness.root(context);
    const id = await root.commit(
      (tx) =>
        tx.createTask(
          sleeper,
          { at: 2000 },
          {
            ownership: { kind: "conversation" },
            background: true,
          },
        ),
      context,
    );
    harness.resume();
    await expect
      .poll(async () => (await harness!.getTask(id, context))?.state.status)
      .toBe("sleeping");
    await harness.waitForTask(legacyTaskId, context);
    expect(harness.wake()).toEqual({ active: false, at: 2000 });
    await harness.close(context);
    harness = await open();
    expect((await harness.getTask(id, context))?.state).toEqual({
      status: "sleeping",
      until: 2000,
      checkpoint: { phase: "deliver" },
    });
    harness.resume();
    expect(
      (await harness.inspect(context)).tasks.find((task) => task.record.id === id)?.state,
    ).toEqual({
      kind: "sleeping",
      until: 2000,
    });
    expect(starts).toBe(1);
    expect(deliveries).toBe(0);
    await harness.close(context);
    now = 2000;
    harness = await open();
    expect((await harness.waitForTask(id, context)).state).toEqual({
      status: "terminal",
      outcome: { status: "completed", result: null },
    });
    await harness.close(context);
    harness = await open();
    await harness.waitForTask(id, context);
    expect(starts).toBe(1);
    expect(deliveries).toBe(1);
    expect((await harness.inspect(context)).tasks).toEqual([]);
  } finally {
    await harness?.close(context);
    await rm(directory, { recursive: true, force: true });
  }
});

test("real Durable 1.4 data preserves rows, migrates pi.live, and recovers tasks across restarts", async () => {
  const directory = await mkdtemp(join(tmpdir(), "batty-durable-14-"));
  const path = join(directory, "durable14.sqlite");
  let harness: Harness | undefined;
  let now = 1000;
  let deliveries = 0;
  let sleepingDeliveries = 0;
  const sleeper = defineTask<{ at: number }, { phase: "deliver" }, null>({
    name: "test.sleeper",
    version: 1,
    initial: () => ({ phase: "deliver" }),
    phases: {
      deliver: (_task, runtime, ctx) => {
        sleepingDeliveries++;
        return runtime.commit(
          () => ({ status: "terminal", outcome: { status: "completed", result: null } }),
          ctx,
        );
      },
    },
    abort: (_task, runtime, ctx) =>
      runtime.commit(() => ({ status: "terminal", outcome: { status: "aborted" } }), ctx),
  });
  const registry = createRegistry();
  registry.install(
    defineExtension({
      name: "durable14",
      tasks: [migrationTask(() => deliveries++), sleeper],
    }),
  );
  const open = async () =>
    Harness.open(
      await openNodeSqliteStorage(path),
      {
        models: createModels(),
        registry,
        now: () => now,
        onWake: () => {},
        settings: { restartLimit: 2 },
      },
      context,
    );
  try {
    const before = restoreLegacy(path, durable14Fixture);
    expect(schemaVersion(path)).toBe(2);
    const storage = await openNodeSqliteStorage(path);
    try {
      expect(schemaVersion(path)).toBe(2);
      const db = new DatabaseSync(path, { readOnly: true });
      try {
        for (const [table, rows] of Object.entries(before)) {
          expect(db.prepare(`SELECT * FROM "${table}" ORDER BY rowid`).all()).toEqual(rows);
        }
      } finally {
        db.close();
      }
    } finally {
      await storage.close(context);
    }
    harness = await open();
    const root = await harness.root(context);
    expect(root.id).toBe(1);
    expect(await harness.snapshot(legacyDocument, root.id, context)).toEqual({
      items: ["written by Durable 1.4", "second committed delta"],
    });
    expect(await harness.snapshot(LiveDoc, root.id, context)).toEqual({
      compactionFailure: { taskId: durable14.pending, trigger: "manual", error: "fixture failure" },
    });
    expect(await harness.getTask(durable14.running, context)).toMatchObject({
      restarts: 1,
      state: { checkpoint: { phase: "deliver" } },
    });
    expect((await harness.waitForTask(durable14.running, context)).state).toEqual({
      status: "terminal",
      outcome: { status: "completed", result: 42 },
    });
    expect((await harness.waitForTask(durable14.pending, context)).state).toEqual({
      status: "terminal",
      outcome: { status: "completed", result: 43 },
    });
    expect(deliveries).toBe(2);
    expect(sleepingDeliveries).toBe(0);
    await expect.poll(() => harness!.wake()).toEqual({ active: false, at: 2000 });
    await root.commit(async (tx) => {
      (await tx.doc(legacyDocument, root.id)).items.push("written by Durable 1.5");
      (await tx.doc(LiveDoc, root.id)).compactionFailure!.error = "written by Durable 1.5";
    }, context);
    await harness.close(context);
    harness = undefined;
    const db = new DatabaseSync(path, { readOnly: true });
    try {
      const liveVersion = db
        .prepare("SELECT max(version) AS version FROM document_revisions WHERE document_id = 2")
        .get()?.version;
      expect(liveVersion).toBe(3);
      expect(db.prepare("PRAGMA integrity_check").get()?.integrity_check).toBe("ok");
    } finally {
      db.close();
    }
    harness = await open();
    expect(await harness.snapshot(legacyDocument, root.id, context)).toEqual({
      items: ["written by Durable 1.4", "second committed delta", "written by Durable 1.5"],
    });
    expect(await harness.snapshot(LiveDoc, root.id, context)).toEqual({
      compactionFailure: {
        taskId: durable14.pending,
        trigger: "manual",
        error: "written by Durable 1.5",
      },
    });
    expect((await harness.getTask(durable14.sleeping, context))?.state).toEqual({
      status: "sleeping",
      until: 2000,
      checkpoint: { phase: "deliver" },
    });
    await harness.close(context);
    now = 2000;
    harness = await open();
    expect((await harness.waitForTask(durable14.sleeping, context)).state).toEqual({
      status: "terminal",
      outcome: { status: "completed", result: null },
    });
    await harness.close(context);
    harness = await open();
    await harness.waitForTask(durable14.running, context);
    await harness.waitForTask(durable14.pending, context);
    await harness.waitForTask(durable14.sleeping, context);
    expect(deliveries).toBe(2);
    expect(sleepingDeliveries).toBe(1);
    expect((await harness.inspect(context)).tasks).toEqual([]);
  } finally {
    await harness?.close(context);
    await rm(directory, { recursive: true, force: true });
  }
});

for (const mode of ["generation", "tool"] as const) {
  test(`real 1.4 in-flight ${mode} migrates and settles its existing input once`, async () => {
    const directory = await mkdtemp(join(tmpdir(), `batty-durable14-${mode}-`));
    const path = join(directory, "turn.sqlite");
    let harness: Harness | undefined;
    let toolExecutions = 0;
    const attempts: number[] = [];
    const faux = fauxProvider({ tokensPerSecond: 100000, models: [{ id: "migration" }] });
    const models = createModels();
    models.setProvider(faux.provider);
    const registry = createRegistry();
    registry.install(
      defineExtension({
        name: "migration-turn",
        tools: [
          defineTool({
            name: "migration-tool",
            description: "Replay-safe fixture tool",
            parameters: { type: "object", properties: {}, additionalProperties: false },
            replay: "safe",
            execute: async () => {
              toolExecutions++;
              return { output: [{ type: "text", text: "Recovered tool result" }] };
            },
          }),
        ],
      }),
    );
    const open = () =>
      openNodeSqliteStorage(path).then((storage) =>
        Harness.open(
          storage,
          {
            models,
            registry,
            settings: { retry: { enabled: true, maxRetries: 1, baseDelayMs: 1 } },
          },
          context,
        ),
      );
    try {
      restoreLegacy(
        path,
        mode === "generation" ? durable14GenerationFixture : durable14ToolFixture,
      );
      harness = await open();
      const root = await harness.root(context);
      expect((await harness.snapshot(LiveDoc, root.id, context))?.run).toMatchObject({
        taskId: 9,
        inputs: [8],
        turns: 0,
      });
      faux.setResponses([
        async () => {
          attempts.push((await harness!.snapshot(LiveDoc, root.id, context))!.generation!.attempt);
          return fauxAssistantMessage("Recovered final answer");
        },
      ]);
      const submission = await harness.submission(8 as SubmissionId, context);
      expect(submission).toBeDefined();
      await root.waitForIdle(context);
      expect(await submission!.wait(context)).toMatchObject({ status: "done" });
      expect(attempts).toEqual(mode === "generation" ? [2] : [1]);
      expect(faux.state.callCount).toBe(1);
      expect(toolExecutions).toBe(mode === "tool" ? 1 : 0);
      const messages = (await root.context(context)).messages;
      expect(messages.filter((message) => message.role === "user")).toHaveLength(1);
      expect(
        messages.filter(
          (message) =>
            message.role === "assistant" &&
            JSON.stringify(message.content).includes("Recovered final answer"),
        ),
      ).toHaveLength(1);
      if (mode === "tool") {
        expect(messages.filter((message) => message.role === "toolResult")).toMatchObject([
          {
            toolCallId: "migration-call",
            content: [{ type: "text", text: "Recovered tool result" }],
          },
        ]);
        expect(await harness.getTask(12 as TaskId, context)).toMatchObject({
          version: 3,
          state: { status: "terminal", outcome: { status: "completed" } },
        });
      }
      expect(await harness.getTask(9 as TaskId, context)).toMatchObject({
        version: 2,
        state: { status: "terminal", outcome: { status: "completed" } },
      });
      expect((await harness.snapshot(LiveDoc, root.id, context))?.run).toBeUndefined();
      const repeated = await root.submit(
        {
          type: "input",
          content: `Resume this ${mode} once`,
          requestId: `migration-${mode}-input`,
        },
        context,
      );
      expect(repeated.id).toBe(8);
      await harness.close(context);
      harness = await open();
      const reopened = await harness.root(context);
      await reopened.waitForIdle(context);
      expect((await reopened.context(context)).messages).toEqual(messages);
      expect(faux.state.callCount).toBe(1);
      expect(toolExecutions).toBe(mode === "tool" ? 1 : 0);
      const db = new DatabaseSync(path, { readOnly: true });
      try {
        expect(db.prepare("SELECT count(*) AS count FROM submissions").get()?.count).toBe(1);
        expect(
          db
            .prepare("SELECT max(version) AS version FROM document_revisions WHERE document_id = 2")
            .get()?.version,
        ).toBe(3);
      } finally {
        db.close();
      }
    } finally {
      await harness?.close(context);
      await rm(directory, { recursive: true, force: true });
    }
  });
}

test("an interrupted real 1.4 model request with no retry budget settles unanswered without resending", async () => {
  const directory = await mkdtemp(join(tmpdir(), "batty-durable14-no-retry-"));
  const path = join(directory, "turn.sqlite");
  let harness: Harness | undefined;
  const faux = fauxProvider({ models: [{ id: "migration" }] });
  const models = createModels();
  models.setProvider(faux.provider);
  try {
    restoreLegacy(path, durable14GenerationFixture);
    harness = await Harness.open(
      await openNodeSqliteStorage(path),
      {
        models,
        registry: createRegistry(),
        settings: { retry: { enabled: true, maxRetries: 0 } },
      },
      context,
    );
    const root = await harness.root(context);
    const submission = await harness.submission(8 as SubmissionId, context);
    await root.waitForIdle(context);
    expect(await submission!.wait(context)).toMatchObject({
      status: "unanswered",
      reason: "interrupted",
    });
    expect((await harness.snapshot(LiveDoc, root.id, context))?.runFailure).toMatchObject({
      reason: "interrupted",
      inputs: [8],
    });
    expect(faux.state.callCount).toBe(0);
    expect(
      (await root.context(context)).messages.filter((message) => message.role === "user"),
    ).toHaveLength(1);
    expect((await harness.inspect(context)).tasks).toEqual([]);
  } finally {
    await harness?.close(context);
    await rm(directory, { recursive: true, force: true });
  }
});

test("a real process crash ends its restart-limited task and a new task recovers the work", async () => {
  const directory = await mkdtemp(join(tmpdir(), "batty-durable-crash-"));
  const path = join(directory, "crash.sqlite");
  let harness: Harness | undefined;
  try {
    restoreLegacy(path);
    const childPath = join(directory, "crash.mjs");
    const packageUrl = (name: string, file: string) =>
      new URL(`../../node_modules/@earendil-works/${name}/dist/${file}`, import.meta.url).href;
    await writeFile(
      childPath,
      `
      import { Harness, createRegistry, defineExtension, defineTask } from ${JSON.stringify(packageUrl("pi-durable", "index.js"))};
      import { openNodeSqliteStorage } from ${JSON.stringify(packageUrl("pi-durable", "storage/sqlite/node.js"))};
      import { createModels } from ${JSON.stringify(packageUrl("pi-ai", "models.js"))};
      import { BACKGROUND_CONTEXT as context } from ${JSON.stringify(packageUrl("chord", "context/index.js"))};
      const task = defineTask({ name: "test.migration-task", version: 1,
        initial: () => ({ phase: "deliver" }),
        phases: { deliver: async () => process.exit(73) }, abort: async () => {} });
      const registry = createRegistry();
      registry.install(defineExtension({ name: "crash-test", tasks: [task] }));
      const harness = await Harness.open(await openNodeSqliteStorage(${JSON.stringify(path)}), { models: createModels(), registry }, context);
      await harness.waitForTask(8, context);
    `,
    );
    const crashed = spawnSync(process.execPath, [childPath], { encoding: "utf8", timeout: 10_000 });
    expect(crashed.error, crashed.stderr).toBeUndefined();
    expect(crashed.status, crashed.stderr).toBe(73);
    const db = new DatabaseSync(path, { readOnly: true });
    try {
      expect(db.prepare("SELECT status FROM tasks WHERE id = 8").get()?.status).toBe("running");
    } finally {
      db.close();
    }
    const registry = createRegistry();
    let executions = 0;
    registry.install(
      defineExtension({ name: "recovery-test", tasks: [migrationTask(() => executions++)] }),
    );
    const reports: { kind: string; reason?: string }[] = [];
    harness = await Harness.open(
      await openNodeSqliteStorage(path),
      {
        models: createModels(),
        registry,
        settings: { restartLimit: 1 },
        onReport: (report) => {
          reports.push(report);
        },
      },
      context,
    );
    expect((await harness.waitForTask(legacyTaskId, context)).state).toMatchObject({
      status: "terminal",
      outcome: { status: "faulted", error: { detail: { reason: "restart_limit" } } },
    });
    expect((await harness.inspect(context)).tasks).toEqual([]);
    expect(harness.wake().active).toBe(false);
    expect(reports.filter((report) => report.kind === "task_faulted")).toMatchObject([
      { reason: "restart_limit" },
    ]);
    expect(executions).toBe(0);
    const root = await harness.root(context);
    const replacement = await root.commit(
      (tx) =>
        tx.createTask(
          migrationTask(),
          { value: 42 },
          {
            ownership: { kind: "conversation" },
            background: true,
          },
        ),
      context,
    );
    expect(replacement).not.toBe(legacyTaskId);
    expect((await harness.waitForTask(replacement, context)).state).toEqual({
      status: "terminal",
      outcome: { status: "completed", result: 42 },
    });
    expect(executions).toBe(1);
  } finally {
    await harness?.close(context);
    await rm(directory, { recursive: true, force: true });
  }
});
